import random,itertools
from offline_discovery.banks import build_exact_bank, ExactLookup
class C:
 def __init__(self,cid,rng): self.cid=cid; self.length=len(rng); self.rng=rng

def brute(clusters):
 s={}
 for c in clusters:
  dom=[]
  for lo,hi in c.rng:
   vals=[v for v in range(lo,hi+1) if v!=1514]
   dom.append(vals)
  if any(not d for d in dom): continue
  for k in itertools.product(*dom):
   s.setdefault(k,[]).append(c.cid)
 return s
for trial in range(500):
 L=random.randint(2,4)
 n=random.randint(0,8)
 cs=[]
 for i in range(n):
  rng=[]
  for j in range(L):
   if random.random()<.3:
    # near hole
    lo=random.randint(1511,1515); hi=random.randint(lo,1517)
   else:
    lo=random.randint(0,10); hi=random.randint(lo,10)
   rng.append([lo,hi])
  cs.append(C(i,rng))
 # random global priority permutation
 prio=list(range(n)); random.shuffle(prio); rank={cid:i for i,cid in enumerate(prio)}
 cap=random.randint(0,20)
 total,tables=build_exact_bank(cs,cap,rank)
 b=brute(cs); exp=min(len(b),cap+1)
 if total!=exp:
  print('countfail',trial,L,n,cap,total,exp,cs); break
 if len(b)<=cap:
  lookup=ExactLookup(tables)
  for key in b:
   want=min(b[key],key=lambda cid: rank[cid])
   # direct table
   found=None
   for length,tab,minrank in lookup.groups:
    if length==len(key):
     val=tab.get(key)
     if val: found=val[1]
   if found!=want:
    print('actionfail',trial,key,want,found,tables,rank); raise SystemExit
  # for random keys not in b lookup maybe not mapped but intervals may cover? ensure all interval points in b
else:
 print('all ok')
